template.script:
(function(){
  /* ── Data tables ── */
  var AUD={
    idea_personal:    {urgency:.85,riskMult:1.20,mktCapture:.60,rec:'Start with a lean MVP targeting your first 10–20 paying customers. Budget 4–6 months of focused development with a reliable technical partner.'},
    idea_funded:      {urgency:.95,riskMult:1.70,mktCapture:.75,rec:'Speed to a working product is everything. Investors expect milestones on schedule — a strong development partner can halve your time-to-demo.'},
    unsatisfied_team: {urgency:.90,riskMult:1.50,mktCapture:.65,rec:'Audit your current output vs monthly spend. Switching to the right partner typically saves 40–60% long-term and recovers 3–6 months of velocity.'},
    mvp_investment:   {urgency:.80,riskMult:1.40,mktCapture:.70,rec:'Prioritise scalability, code quality, and feature delivery speed. The right team pays for itself within 3–4 months.'},
    mvp_ai:           {urgency:.88,riskMult:1.60,mktCapture:.60,rec:'Get a professional technical audit before scaling marketing or pitching investors. Fixing AI-built MVPs early costs 3x less.'},
    non_technical:    {urgency:.75,riskMult:1.10,mktCapture:.50,rec:'Start with a discovery and prototype phase before committing to full development. Validate cheaply, then scale with confidence.'},
  };
  var ST={
    b2b:        {competition:.60,baseMonths:5},
    b2c:        {competition:.85,baseMonths:6},
    marketplace:{competition:.78,baseMonths:9},
    enterprise: {competition:.50,baseMonths:14},
  };
  var CMP={
    mvp:       {monthlyMin:8000,  monthlyMax:15000, timeMult:.70},
    standard:  {monthlyMin:15000, monthlyMax:28000, timeMult:1.00},
    complex:   {monthlyMin:28000, monthlyMax:50000, timeMult:1.45},
    enterprise:{monthlyMin:45000, monthlyMax:90000, timeMult:1.85},
  };
  var USR={small:{sf:1.00},medium:{sf:1.20},large:{sf:1.55},xlarge:{sf:1.95}};
  var TL={asap:{um:1.50,cp:1.30},short:{um:1.20,cp:1.10},medium:{um:1.00,cp:1.00},long:{um:0.80,cp:0.90}};
  var AI={
    no_ai:    {cm:1.00,tm:1.00,note:''},
    ai_api:   {cm:1.20,tm:1.15,note:'AI API integration adds prompt engineering, reliability handling and ongoing API cost.'},
    ai_custom:{cm:1.65,tm:1.50,note:'Custom ML requires data pipelines, model training, evaluation and MLOps infrastructure.'},
    ai_core:  {cm:2.00,tm:1.80,note:'AI-first products need significant R&D, data engineering and specialist AI/ML talent.'},
  };
  var IND={
    general:   {cm:1.00,tm:1.00,note:''},
    ecommerce: {cm:1.05,tm:1.05,note:''},
    hr_ops:    {cm:1.10,tm:1.08,note:''},
    education: {cm:1.10,tm:1.08,note:''},
    legal:     {cm:1.30,tm:1.25,note:'Legal domain complexity and data sensitivity add meaningful scope.'},
    healthcare:{cm:1.50,tm:1.45,note:'HIPAA compliance, audit trails and security certification add ~45% to cost and timeline.'},
    fintech:   {cm:1.55,tm:1.50,note:'PCI DSS and SOC 2 require security audits, penetration testing and compliance work.'},
  };

  /* ── Helpers ── */
  var fmt  = function(n){return '$'+Math.round(n).toLocaleString();};
  var fmtK = function(n){var v=Math.round(n);return v>=1000?'$'+(v/1000).toFixed(0)+'K':fmt(v);};
  var flt  = function(id){return parseFloat(document.getElementById(id).value)||0;};
  var sel  = function(id){return document.getElementById(id).value;};

  function monthlyBuild(ck,uk,tk,aik,ik){var c=CMP[ck],u=USR[uk],t=TL[tk],ai=AI[aik]||AI.no_ai,ind=IND[ik]||IND.general;return{min:Math.round(c.monthlyMin*u.sf*t.cp*ai.cm*ind.cm),max:Math.round(c.monthlyMax*u.sf*t.cp*ai.cm*ind.cm)};}
  function buildTime(sk,ck,budget,aik,ik){var base=ST[sk].baseMonths;var sp=budget>=200000?.80:budget>=100000?.90:budget>=50000?1.00:1.25;var ai=AI[aik]||AI.no_ai,ind=IND[ik]||IND.general;return Math.min(36,Math.max(2,Math.round(base*CMP[ck].timeMult*sp*ai.tm*ind.tm)));}
  function oppScore(ak,sk,ck,uk,tk,aik,ik,budget,rev){
    var a=AUD[ak],s=ST[sk],t=TL[tk],mb=monthlyBuild(ck,uk,tk,aik,ik),bt=buildTime(sk,ck,budget,aik,ik);
    var fit=Math.min(budget/Math.max(mb.min*bt,1),1),mkt=1-s.competition,urg=Math.min(t.um/1.5,1);
    return Math.round(Math.min(99,Math.max(5,(fit*40)+(mkt*30)+(a.mktCapture*20)+(urg*10))));
  }
  function monthlyLost(rev,ak,sk,tk){return Math.round((rev/12)*AUD[ak].urgency*ST[sk].competition*TL[tk].um);}
  function delayLoss(mo,months,mult){var t=0;for(var i=0;i<months;i++)t+=mo*Math.pow(1.05,i);return Math.round(t*mult);}
  function verdict(sc){if(sc>=80)return{text:'Strong Opportunity',cls:'opp-strong'};if(sc>=60)return{text:'Good Opportunity',cls:'opp-good'};if(sc>=40)return{text:'Moderate — Act Strategically',cls:'opp-moderate'};if(sc>=20)return{text:'Challenging — Plan Carefully',cls:'opp-challenging'};return{text:'High Risk — Seek Guidance',cls:'opp-risky'};}

  var TEAM_ROLES={
    designer:{icon:'🎨',label:'UI/UX Designer',    desc:'Branding, wireframes, user flows & visual design'},
    frontend:{icon:'💻',label:'Frontend Engineer',  desc:'React/Vue, responsive UI & performance'},
    backend: {icon:'⚙️',label:'Backend Engineer',   desc:'APIs, database, business logic & integrations'},
    sqa:     {icon:'🧪',label:'QA / Test Engineer', desc:'Manual & automated testing, release sign-off'},
    pm:      {icon:'📋',label:'Project Manager',    desc:'Sprint planning, delivery & stakeholder comms'},
    devops:  {icon:'🔧',label:'DevOps Engineer',    desc:'CI/CD pipelines, cloud infrastructure & monitoring'},
    aiml:    {icon:'🤖',label:'AI / ML Engineer',   desc:'Model training, data pipelines & MLOps'},
    analyst: {icon:'📊',label:'Business Analyst',   desc:'Requirements, domain research & user stories'},
    support: {icon:'🛟',label:'Support Engineer',   desc:'Post-launch support, incidents & onboarding'},
  };
  function calcTeam(ck,aik,ik,uk){
    var t={designer:{min:1,max:1},frontend:{min:1,max:2},backend:{min:1,max:2},sqa:{min:1,max:1},pm:{min:1,max:1},devops:{min:0,max:1},aiml:{min:0,max:0},analyst:{min:0,max:1},support:{min:0,max:0}};
    if(ck==='standard') {t.backend.max=3;}
    if(ck==='complex')  {t.frontend.min=2;t.frontend.max=3;t.backend.min=2;t.backend.max=4;t.devops.min=1;t.analyst.min=1;}
    if(ck==='enterprise'){t.frontend.min=2;t.frontend.max=4;t.backend.min=3;t.backend.max=6;t.sqa.max=2;t.pm.max=2;t.devops.min=1;t.analyst.min=1;t.support.min=1;t.support.max=1;}
    if(aik==='ai_api')   {t.aiml.max=1;}
    if(aik==='ai_custom'){t.aiml.min=1;t.aiml.max=2;}
    if(aik==='ai_core')  {t.aiml.min=2;t.aiml.max=3;t.backend.min=Math.max(t.backend.min,2);}
    if(ik==='healthcare'||ik==='fintech'||ik==='legal'){t.sqa.min=1;t.analyst.min=1;}
    if(uk==='large'||uk==='xlarge'){t.devops.min=1;t.support.min=1;t.support.max=1;}
    var res=[];for(var k in t){if(t[k].max>0)res.push({key:k,min:t[k].min,max:t[k].max});}
    return res;
  }

  function validate(){
    var ok=true,em=document.getElementById('fEmail').value.trim(),rv=flt('fRevenue'),bud=flt('fBudget');
    var show=function(id,v){var el=document.getElementById(id);if(v){el.classList.add('show');ok=false;}else el.classList.remove('show');};
    if(!em||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)){document.getElementById('errEmail').textContent=em?'Invalid email':'Email is required';show('errEmail',true);}else show('errEmail',false);
    show('errRevenue',rv<=0); show('errBudget',bud<=0);
    return ok;
  }

  document.getElementById('calcBtn').addEventListener('click',function(){
    if(!validate())return;
    var ak=sel('fAudience'),sk=sel('fSaasType'),ck=sel('fComplexity'),uk=sel('fUsers'),tk=sel('fTimeline');
    var aik=sel('fAI'),ik=sel('fIndustry');
    var rev=flt('fRevenue'),budget=flt('fBudget');
    var a=AUD[ak];

    var mb   = monthlyBuild(ck,uk,tk,aik,ik);
    var bt   = buildTime(sk,ck,budget,aik,ik);
    var sc   = oppScore(ak,sk,ck,uk,tk,aik,ik,budget,rev);
    var mo   = monthlyLost(rev,ak,sk,tk);
    var l6   = delayLoss(mo,6,a.riskMult);
    var l12  = delayLoss(mo,12,a.riskMult);
    var tbMin= mb.min*bt, tbMax=mb.max*bt;
    var roi  = rev>0?Math.ceil(tbMax/(rev/12)):null;
    var verd = verdict(sc);

    /* Badge + ring */
    var badge=document.getElementById('oppBadge');
    badge.textContent=verd.text; badge.className='sc-opp-badge '+verd.cls;
    var ringCol=sc>=80?'#2e7d32':sc>=60?'#1565c0':sc>=40?'#f57f17':'#c62828';
    document.getElementById('rScore').textContent=sc;
    document.getElementById('rVerdict').textContent=verd.text;
    document.getElementById('rVerdict').style.color=ringCol;
    var saasLbls={b2b:'B2B SaaS',b2c:'B2C SaaS',marketplace:'Marketplace',enterprise:'Enterprise'};
    var cmpLbls={mvp:'Simple MVP',standard:'Standard SaaS',complex:'Complex Platform',enterprise:'Enterprise-grade'};
    var indLbls={general:'General',ecommerce:'E-commerce',hr_ops:'HR/Ops',education:'EdTech',legal:'Legal',healthcare:'Healthcare',fintech:'Fintech'};
    document.getElementById('rScoreSub').textContent=(saasLbls[sk]||sk)+' · '+(indLbls[ik]||ik)+' · '+(cmpLbls[ck]||ck);
    var ringEl=document.getElementById('ringFill');
    ringEl.style.stroke=ringCol;
    setTimeout(function(){ringEl.style.strokeDashoffset=(201.1*(1-sc/100)).toFixed(1);},60);

    /* Delay cost */
    document.getElementById('rMonthly').textContent=fmt(mo);
    document.getElementById('rLoss6').textContent=fmt(l6);

    /* Metrics row */
    document.getElementById('rMonthlyBuild').textContent=fmtK(mb.min)+' – '+fmtK(mb.max);
    document.getElementById('rBuildTime').textContent=bt+(bt===1?' month':' months');
    document.getElementById('rROI').textContent=roi?'~'+roi+(roi===1?' month':' months'):'N/A';

    /* Complexity notes */
    var notes=[];
    if(AI[aik]&&AI[aik].note)notes.push(AI[aik].note);
    if(IND[ik]&&IND[ik].note)notes.push(IND[ik].note);
    var noteEl=document.getElementById('rBuildNotes');
    noteEl.innerHTML=notes.map(function(n){return'<span class="sc-build-note">⚙ '+n+'</span>';}).join('');
    noteEl.style.display=notes.length?'block':'none';

    /* Team chips */
    var team=calcTeam(ck,aik,ik,uk);
    var tMin=team.reduce(function(s,r){return s+r.min;},0);
    var tMax=team.reduce(function(s,r){return s+r.max;},0);
    document.getElementById('rTeamSize').textContent=tMin+'–'+tMax+' total';
    document.getElementById('rTeamGrid').innerHTML=team.map(function(r){
      var ro=TEAM_ROLES[r.key];
      var cnt=r.min===r.max?r.min+'×':(r.min+'–'+r.max+'×');
      return'<span class="sc-team-chip">'+cnt+' '+ro.label.split(' ').slice(0,2).join(' ')+'</span>';
    }).join('');

    /* Show */
    document.getElementById('emptyState').style.display='none';
    var rc=document.getElementById('resContent');
    rc.style.display='flex';rc.style.flexDirection='column';rc.style.flex='1';

    window._audit={ak:ak,sk:sk,ck:ck,uk:uk,tk:tk,aik:aik,ik:ik,rev:rev,budget:budget,sc:sc,mo:mo,l6:l6,l12:l12,mb:mb,tbMin:tbMin,tbMax:tbMax,bt:bt,roi:roi,verd:verd,a:a,tMin:tMin,tMax:tMax};

    /* Auto-save calculator result as a lead (requires email) */
    var _em=document.getElementById('fEmail').value.trim();
    if(_em){fetch('/saas-calculator/submit-lead',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:_em,leadType:'calculator',audienceType:ak,saasType:sk,complexityKey:ck,usersKey:uk,timelineKey:tk,aiKey:aik,industryKey:ik,revenueGoal:rev,budget:budget,source:'saas_audit_calculator',auditResults:{opportunityScore:sc,monthlyRevLost:mo,loss6Months:l6,loss12Months:l12,monthlyBuildMin:mb?mb.min:0,monthlyBuildMax:mb?mb.max:0,totalBudgetMin:tbMin,totalBudgetMax:tbMax,buildTimeline:bt,roiMonths:roi||0,verdict:verd?verd.text:'',teamSize:tMin+'–'+tMax+' people'}})}).catch(function(){});}
  });

  document.getElementById('openAuditBtn').addEventListener('click',function(){
    if(!window._audit)return;
    var d=window._audit;
    document.getElementById('modalSub').textContent='Score '+d.sc+'/100 · '+d.verd.text+' · Monthly loss if delayed: '+fmt(d.mo)+' · 12-month risk: '+fmt(d.l12);
    document.getElementById('rRecommendation').textContent=d.a.rec;
    document.getElementById('leadOk').style.display='none';
    document.getElementById('leadSubmit').style.display='block';
    document.getElementById('auditOverlay').classList.add('on');
  });

  document.getElementById('closeModal').addEventListener('click',function(){document.getElementById('auditOverlay').classList.remove('on');});
  document.getElementById('auditOverlay').addEventListener('click',function(e){if(e.target===document.getElementById('auditOverlay'))document.getElementById('auditOverlay').classList.remove('on');});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')document.getElementById('auditOverlay').classList.remove('on');});

  document.getElementById('leadSubmit').addEventListener('click',function(){
    var name=document.getElementById('lfName').value.trim();
    if(!name){alert('Please enter your name.');return;}
    var d=window._audit||{};
    var payload={
      name:name,phone:document.getElementById('lfPhone').value.trim(),
      company:document.getElementById('lfCompany').value.trim(),role:document.getElementById('lfRole').value.trim(),
      challenge:document.getElementById('lfChallenge').value.trim(),
      email:document.getElementById('fEmail').value.trim(),
      website:document.getElementById('fWebsite').value.trim(),
      audienceType:d.ak,saasType:d.sk,complexityKey:d.ck,usersKey:d.uk,timelineKey:d.tk,aiKey:d.aik,industryKey:d.ik,
      revenueGoal:d.rev,budget:d.budget,
      auditResults:{
        opportunityScore:d.sc,monthlyRevLost:d.mo,loss6Months:d.l6,loss12Months:d.l12,
        monthlyBuildMin:d.mb?d.mb.min:0,monthlyBuildMax:d.mb?d.mb.max:0,
        totalBudgetMin:d.tbMin,totalBudgetMax:d.tbMax,
        buildTimeline:d.bt,roiMonths:d.roi,verdict:d.verd?d.verd.text:'',teamSize:(d.tMin||0)+'–'+(d.tMax||0)+' people',
      },
      source:'saas_audit_calculator',
      leadType:'audit_request',
    };
    fetch('/saas-calculator/submit-lead',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).catch(function(){});
    document.getElementById('leadSubmit').style.display='none';
    document.getElementById('leadOk').style.display='block';
    var t=document.getElementById('toast');t.textContent='Thank you! We will be in touch within 24 hours.';t.classList.add('on');setTimeout(function(){t.classList.remove('on');},4500);
  });
})();
